import type pg from 'pg';
import { withTransaction } from './pool.js';

/**
 * Tenant isolation: Shared Database, Separate Schema (ТЗ, п. 4.2).
 * Each forum lives in its own PostgreSQL schema named `tenant_<id>`.
 */

const SCHEMA_RE = /^tenant_[a-z0-9_]{1,50}$/;

/** Builds the schema name for a tenant id. Ids are generated by us, but we still validate. */
export function tenantSchemaName(tenantId: string): string {
  const name = `tenant_${tenantId.replace(/-/g, '_').toLowerCase()}`;
  assertTenantSchema(name);
  return name;
}

/**
 * Throws unless `schema` is a well-formed tenant schema name.
 * Schema names cannot be passed as query parameters, so this check is what
 * keeps identifiers safe to interpolate.
 */
export function assertTenantSchema(schema: string): void {
  if (!SCHEMA_RE.test(schema)) {
    throw new Error(`Invalid tenant schema name: ${schema}`);
  }
}

/**
 * Runs `fn` in a transaction whose `search_path` is pinned to the tenant schema.
 * `SET LOCAL` resets at the end of the transaction, so a pooled connection can
 * never leak one forum's search_path into another forum's request.
 */
export async function withTenant<T>(
  schema: string,
  fn: (client: pg.PoolClient) => Promise<T>,
): Promise<T> {
  assertTenantSchema(schema);
  return withTransaction(async (client) => {
    await client.query(`SET LOCAL search_path TO "${schema}", public`);
    return fn(client);
  });
}
